-- Extend plant_species into the full Smart Plant Master schema and
-- import Samak's 348-species starter database (curated from IndiaPlants,
-- eFlora of India, Botanical Survey of India and the CPWD Landscape
-- Handbook). This is the plant-intelligence backbone the AI designer,
-- BOQ, nursery and Samak Care modules will query against.
--
-- A botanical species can legitimately appear more than once (e.g. Areca
-- Palm as an outdoor landscape palm vs. Areca Palm Indoor as an indoor
-- foliage specimen -- same species, different nursery/use specification).
-- So plant_code (Samak's permanent per-record Plant ID), not botanical
-- name, is the row's real identity going forward.

-- Drop the old one-row-per-species constraint from the original schema.
DO $$
DECLARE cname text;
BEGIN
  SELECT conname INTO cname FROM pg_constraint WHERE conrelid = 'public.plant_species'::regclass AND contype = 'u' AND conkey = (SELECT array_agg(attnum) FROM pg_attribute WHERE attrelid = 'public.plant_species'::regclass AND attname = 'botanical_name');
  IF cname IS NOT NULL THEN
    EXECUTE format('ALTER TABLE public.plant_species DROP CONSTRAINT %I', cname);
  END IF;
END $$;

ALTER TABLE public.plant_species
  ADD COLUMN IF NOT EXISTS plant_code text,
  ADD COLUMN IF NOT EXISTS local_name text,
  ADD COLUMN IF NOT EXISTS family text,
  ADD COLUMN IF NOT EXISTS subcategory text,
  ADD COLUMN IF NOT EXISTS native_status text,
  ADD COLUMN IF NOT EXISTS habit text,
  ADD COLUMN IF NOT EXISTS mature_spread_m numeric,
  ADD COLUMN IF NOT EXISTS lifespan text,
  ADD COLUMN IF NOT EXISTS canopy_form text,
  ADD COLUMN IF NOT EXISTS flower_colour text,
  ADD COLUMN IF NOT EXISTS flowering_months text,
  ADD COLUMN IF NOT EXISTS irrigation_hydrozone text,
  ADD COLUMN IF NOT EXISTS soil_ph text,
  ADD COLUMN IF NOT EXISTS climate_type text,
  ADD COLUMN IF NOT EXISTS drought_tolerance smallint,
  ADD COLUMN IF NOT EXISTS heat_tolerance smallint,
  ADD COLUMN IF NOT EXISTS frost_tolerance smallint,
  ADD COLUMN IF NOT EXISTS pollution_tolerance smallint,
  ADD COLUMN IF NOT EXISTS salinity_tolerance smallint,
  ADD COLUMN IF NOT EXISTS root_risk_notes text,
  ADD COLUMN IF NOT EXISTS toxicity_notes text,
  ADD COLUMN IF NOT EXISTS ai_design_tags text[],
  ADD COLUMN IF NOT EXISTS landscape_uses text[],
  ADD COLUMN IF NOT EXISTS recommended_spacing text,
  ADD COLUMN IF NOT EXISTS planting_season text,
  ADD COLUMN IF NOT EXISTS pruning_requirement text,
  ADD COLUMN IF NOT EXISTS fertilizer_requirement text,
  ADD COLUMN IF NOT EXISTS pollinator_value text,
  ADD COLUMN IF NOT EXISTS fauna_value text,
  ADD COLUMN IF NOT EXISTS ecological_value text,
  ADD COLUMN IF NOT EXISTS nursery_spec text,
  ADD COLUMN IF NOT EXISTS pot_bag_size text,
  ADD COLUMN IF NOT EXISTS standard_height_girth text,
  ADD COLUMN IF NOT EXISTS indicative_buy_price numeric,
  ADD COLUMN IF NOT EXISTS indicative_sell_price numeric,
  ADD COLUMN IF NOT EXISTS delhi_ncr_fit smallint,
  ADD COLUMN IF NOT EXISTS arid_nw_fit smallint,
  ADD COLUMN IF NOT EXISTS himalayan_foothills_fit smallint,
  ADD COLUMN IF NOT EXISTS temperate_hills_fit smallint,
  ADD COLUMN IF NOT EXISTS western_coast_fit smallint,
  ADD COLUMN IF NOT EXISTS deccan_plateau_fit smallint,
  ADD COLUMN IF NOT EXISTS east_ne_humid_fit smallint,
  ADD COLUMN IF NOT EXISTS coastal_south_fit smallint,
  ADD COLUMN IF NOT EXISTS verification_status text,
  ADD COLUMN IF NOT EXISTS data_confidence text,
  ADD COLUMN IF NOT EXISTS primary_sources text,
  ADD COLUMN IF NOT EXISTS samak_preferred text,
  ADD COLUMN IF NOT EXISTS samak_field_rating smallint;

DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'plant_species_drought_tolerance_range_ck') THEN
    ALTER TABLE public.plant_species ADD CONSTRAINT plant_species_drought_tolerance_range_ck CHECK (drought_tolerance IS NULL OR drought_tolerance BETWEEN 1 AND 5);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'plant_species_heat_tolerance_range_ck') THEN
    ALTER TABLE public.plant_species ADD CONSTRAINT plant_species_heat_tolerance_range_ck CHECK (heat_tolerance IS NULL OR heat_tolerance BETWEEN 1 AND 5);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'plant_species_frost_tolerance_range_ck') THEN
    ALTER TABLE public.plant_species ADD CONSTRAINT plant_species_frost_tolerance_range_ck CHECK (frost_tolerance IS NULL OR frost_tolerance BETWEEN 1 AND 5);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'plant_species_pollution_tolerance_range_ck') THEN
    ALTER TABLE public.plant_species ADD CONSTRAINT plant_species_pollution_tolerance_range_ck CHECK (pollution_tolerance IS NULL OR pollution_tolerance BETWEEN 1 AND 5);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'plant_species_salinity_tolerance_range_ck') THEN
    ALTER TABLE public.plant_species ADD CONSTRAINT plant_species_salinity_tolerance_range_ck CHECK (salinity_tolerance IS NULL OR salinity_tolerance BETWEEN 1 AND 5);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'plant_species_delhi_ncr_fit_range_ck') THEN
    ALTER TABLE public.plant_species ADD CONSTRAINT plant_species_delhi_ncr_fit_range_ck CHECK (delhi_ncr_fit IS NULL OR delhi_ncr_fit BETWEEN 1 AND 5);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'plant_species_arid_nw_fit_range_ck') THEN
    ALTER TABLE public.plant_species ADD CONSTRAINT plant_species_arid_nw_fit_range_ck CHECK (arid_nw_fit IS NULL OR arid_nw_fit BETWEEN 1 AND 5);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'plant_species_himalayan_foothills_fit_range_ck') THEN
    ALTER TABLE public.plant_species ADD CONSTRAINT plant_species_himalayan_foothills_fit_range_ck CHECK (himalayan_foothills_fit IS NULL OR himalayan_foothills_fit BETWEEN 1 AND 5);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'plant_species_temperate_hills_fit_range_ck') THEN
    ALTER TABLE public.plant_species ADD CONSTRAINT plant_species_temperate_hills_fit_range_ck CHECK (temperate_hills_fit IS NULL OR temperate_hills_fit BETWEEN 1 AND 5);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'plant_species_western_coast_fit_range_ck') THEN
    ALTER TABLE public.plant_species ADD CONSTRAINT plant_species_western_coast_fit_range_ck CHECK (western_coast_fit IS NULL OR western_coast_fit BETWEEN 1 AND 5);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'plant_species_deccan_plateau_fit_range_ck') THEN
    ALTER TABLE public.plant_species ADD CONSTRAINT plant_species_deccan_plateau_fit_range_ck CHECK (deccan_plateau_fit IS NULL OR deccan_plateau_fit BETWEEN 1 AND 5);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'plant_species_east_ne_humid_fit_range_ck') THEN
    ALTER TABLE public.plant_species ADD CONSTRAINT plant_species_east_ne_humid_fit_range_ck CHECK (east_ne_humid_fit IS NULL OR east_ne_humid_fit BETWEEN 1 AND 5);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'plant_species_coastal_south_fit_range_ck') THEN
    ALTER TABLE public.plant_species ADD CONSTRAINT plant_species_coastal_south_fit_range_ck CHECK (coastal_south_fit IS NULL OR coastal_south_fit BETWEEN 1 AND 5);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'plant_species_samak_field_rating_range_ck') THEN
    ALTER TABLE public.plant_species ADD CONSTRAINT plant_species_samak_field_rating_range_ck CHECK (samak_field_rating IS NULL OR samak_field_rating BETWEEN 1 AND 5);
  END IF;
END $$;

CREATE UNIQUE INDEX IF NOT EXISTS idx_plant_species_plant_code ON public.plant_species (plant_code) WHERE plant_code IS NOT NULL;

ON CONFLICT (plant_code) WHERE plant_code IS NOT NULL DO UPDATE SET
  botanical_name = EXCLUDED.botanical_name,
  common_name = EXCLUDED.common_name,
  category = EXCLUDED.category,
  water_need = EXCLUDED.water_need,
  sunlight = EXCLUDED.sunlight,
  soil_type = EXCLUDED.soil_type,
  growth_rate = EXCLUDED.growth_rate,
  mature_height_m = EXCLUDED.mature_height_m,
  maintenance_level = EXCLUDED.maintenance_level,
  native_region = EXCLUDED.native_region,
  notes = EXCLUDED.notes,
  local_name = EXCLUDED.local_name,
  family = EXCLUDED.family,
  subcategory = EXCLUDED.subcategory,
  native_status = EXCLUDED.native_status,
  habit = EXCLUDED.habit,
  mature_spread_m = EXCLUDED.mature_spread_m,
  lifespan = EXCLUDED.lifespan,
  canopy_form = EXCLUDED.canopy_form,
  flower_colour = EXCLUDED.flower_colour,
  flowering_months = EXCLUDED.flowering_months,
  irrigation_hydrozone = EXCLUDED.irrigation_hydrozone,
  soil_ph = EXCLUDED.soil_ph,
  climate_type = EXCLUDED.climate_type,
  drought_tolerance = EXCLUDED.drought_tolerance,
  heat_tolerance = EXCLUDED.heat_tolerance,
  frost_tolerance = EXCLUDED.frost_tolerance,
  pollution_tolerance = EXCLUDED.pollution_tolerance,
  salinity_tolerance = EXCLUDED.salinity_tolerance,
  root_risk_notes = EXCLUDED.root_risk_notes,
  toxicity_notes = EXCLUDED.toxicity_notes,
  ai_design_tags = EXCLUDED.ai_design_tags,
  landscape_uses = EXCLUDED.landscape_uses,
  recommended_spacing = EXCLUDED.recommended_spacing,
  planting_season = EXCLUDED.planting_season,
  pruning_requirement = EXCLUDED.pruning_requirement,
  fertilizer_requirement = EXCLUDED.fertilizer_requirement,
  pollinator_value = EXCLUDED.pollinator_value,
  fauna_value = EXCLUDED.fauna_value,
  ecological_value = EXCLUDED.ecological_value,
  nursery_spec = EXCLUDED.nursery_spec,
  pot_bag_size = EXCLUDED.pot_bag_size,
  standard_height_girth = EXCLUDED.standard_height_girth,
  indicative_buy_price = EXCLUDED.indicative_buy_price,
  indicative_sell_price = EXCLUDED.indicative_sell_price,
  delhi_ncr_fit = EXCLUDED.delhi_ncr_fit,
  arid_nw_fit = EXCLUDED.arid_nw_fit,
  himalayan_foothills_fit = EXCLUDED.himalayan_foothills_fit,
  temperate_hills_fit = EXCLUDED.temperate_hills_fit,
  western_coast_fit = EXCLUDED.western_coast_fit,
  deccan_plateau_fit = EXCLUDED.deccan_plateau_fit,
  east_ne_humid_fit = EXCLUDED.east_ne_humid_fit,
  coastal_south_fit = EXCLUDED.coastal_south_fit,
  verification_status = EXCLUDED.verification_status,
  data_confidence = EXCLUDED.data_confidence,
  primary_sources = EXCLUDED.primary_sources,
  samak_preferred = EXCLUDED.samak_preferred,
  samak_field_rating = EXCLUDED.samak_field_rating,
  updated_at = now();
